382	    /// Zero all key-material related to the peer
383	    pub fn zero_keys(&self) {
384	        log::trace!("peer.zero_keys");
385	
386	        let mut release: Vec<u32> = Vec::with_capacity(3);
387	        let mut keys = self.peer.keys.lock();
388	
389	        // update key-wheel
390	
391	        if let Some(k) = mem::replace(&mut keys.next, None) {
392	            release.push(k.local_id())
393	        }
394	        if let Some(k) = mem::replace(&mut keys.current, None) {
395	            release.push(k.local_id())
396	        }
397	        if let Some(k) = mem::replace(&mut keys.previous, None) {
398	            release.push(k.local_id())
399	        }
400	        keys.retired.extend(&release[..]);
401	
402	        // update inbound "recv" map
403	        {
404	            let mut recv = self.peer.device.recv.write();
405	            for id in release {
406	                recv.remove(&id);
407	            }
408	        }
409	
410	        // clear encryption state
411	        *self.peer.enc_key.lock() = None;
412	    }
