420	    /// Add a new keypair
421	    ///
422	    /// # Arguments
423	    ///
424	    /// - new: The new confirmed/unconfirmed key pair
425	    ///
426	    /// # Returns
427	    ///
428	    /// A vector of ids which has been released.
429	    /// These should be released in the handshake module.
430	    ///
431	    /// # Note
432	    ///
433	    /// The number of ids to be released can be at most 3,
434	    /// since the only way to add additional keys to the peer is by using this method
435	    /// and a peer can have at most 3 keys allocated in the router at any time.
436	    pub fn add_keypair(&self, new: KeyPair) -> Vec<u32> {
437	        log::trace!("Router, add_keypair: {:?}", new);
438	
439	        let initiator = new.initiator;
440	        let release = {
441	            let new = Arc::new(new);
442	            let mut keys = self.peer.keys.lock();
443	            let mut release = mem::replace(&mut keys.retired, vec![]);
444	
445	            // update key-wheel
446	            if new.initiator {
447	                // start using key for encryption
448	                *self.peer.enc_key.lock() = Some(EncryptionState::new(&new));
449	
450	                // move current into previous
451	                keys.previous = keys.current.as_ref().cloned();
452	                keys.current = Some(new.clone());
453	            } else {
454	                // store the key and await confirmation
455	                keys.previous = keys.next.as_ref().cloned();
456	                keys.next = Some(new.clone());
457	            };
458	
459	            // update incoming packet id map
460	            {
461	                log::trace!("peer.add_keypair: updating inbound id map");
462	                let mut recv = self.peer.device.recv.write();
463	
464	                // purge recv map of previous id
465	                if let Some(k) = &keys.previous {
466	                    recv.remove(&k.local_id());
467	                    release.push(k.local_id());
468	                }
469	
470	                // map new id to decryption state
471	                debug_assert!(!recv.contains_key(&new.recv.id));
472	                recv.insert(
473	                    new.recv.id,
474	                    Arc::new(DecryptionState::new(self.peer.clone(), &new)),
475	                );
476	            }
477	            release
478	        };
479	
480	        // schedule confirmation
481	        if initiator {
482	            debug_assert!(self.peer.enc_key.lock().is_some());
483	            log::trace!("peer.add_keypair: is initiator, must confirm the key");
484	            // attempt to confirm using staged packets
485	            if !self.peer.send_staged() {
486	                // fall back to keepalive packet
487	                self.send_keepalive();
488	                log::debug!("peer.add_keypair: keepalive for confirmation",);
489	            }
490	            log::trace!("peer.add_keypair: key attempted confirmed");
491	        }
492	
493	        debug_assert!(
494	            release.len() <= 3,
495	            "since the key-wheel contains at most 3 keys"
496	        );
497	        release
498	    }
